def over_summary(balls):
    # balls is a list of runs, for example [1, 4, 0, 6, 2, 1]
    # Return (total_runs, big_hits)
    total = 0
    big = 0
    for r in balls:
        total = total + r
        if r >= 4:
            big = big + 1
    # handle empty over automatically (total and big stay 0)
    return (total, big)

print(over_summary([1, 4, 0, 6, 2, 1]))

